    srand(time(NULL));
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string a;
    cin >> a;

    int n = a.length();
    vector<int> b(n);

    for (int i = 0; i < n; ++i) {
        b[i] = (a[i] == 'A');
    }

    vector<pair<int, int>> dp1(n + 1), dp2(n + 1);
    dp1[0] = {1, 0};
    dp2[0] = {0, 1};

