        int cur = i % n;
        int prev = i - 1;

        for (auto c : s[{b[prev], b[cur]}].first) {
            if (!c)
                dp1[i].first += dp1[prev].first;
            else
                dp1[i].second += dp1[prev].first;

            if (!c)
                dp2[i].first += dp2[prev].first;
